from datetime import datetime, timezone
from fastapi.testclient import TestClient
from src.main import app

client = TestClient(app)


def test_health_endpoint():
    """Test the /health endpoint returns correct status and timestamp format."""
    response = client.get("/health")

    assert response.status_code == 200

    data = response.json()
    assert data["status"] == "healthy"
    assert "timestamp" in data

    # Verify timestamp is valid ISO format
    try:
        parsed_time = datetime.fromisoformat(data["timestamp"].replace('Z', '+00:00'))
        # Verify it's a recent timestamp (within last minute)
        now = datetime.now(timezone.utc)
        time_diff = abs((now - parsed_time).total_seconds())
        assert time_diff < 60, "Timestamp should be current"
    except ValueError:
        assert False, "Timestamp should be in valid ISO format"
